sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-19 / D-02: Reservation State Guard. Rejects any initial state or transition not listed below.
    var TRANSITIONS = {
        DRAFT: ['PENDING_APPROVAL', 'CANCELLED'],
        PENDING_APPROVAL: ['APPROVED', 'REJECTED', 'CANCELLED'],
        APPROVED: ['PENDING_ASSIGNMENT', 'WAITLISTED', 'CANCELLED'],
        PENDING_ASSIGNMENT: ['ASSIGNED', 'WAITLISTED', 'CANCELLED'],
        WAITLISTED: ['PENDING_ASSIGNMENT', 'CANCELLED'],
        ASSIGNED: ['READY_FOR_PICKUP', 'ACTIVE', 'PENDING_ASSIGNMENT', 'NO_SHOW', 'CANCELLED'],
        READY_FOR_PICKUP: ['ACTIVE', 'PENDING_ASSIGNMENT', 'NO_SHOW', 'CANCELLED'],
        ACTIVE: ['COMPLETED', 'INTERRUPTED']
        // COMPLETED, REJECTED, CANCELLED, NO_SHOW, INTERRUPTED are terminal
    };

    var to = current.getValue('reservation_state');

    if (current.operation() == 'insert') {
        // Form save = DRAFT, portal = PENDING_APPROVAL, recall replacement (D-26) = PENDING_ASSIGNMENT
        var allowedInsert = to == 'DRAFT' || to == 'PENDING_APPROVAL' ||
            (to == 'PENDING_ASSIGNMENT' && !current.replaces_reservation.nil());
        if (!allowedInsert) {
            gs.addErrorMessage('Invalid initial state ' + to + '.');
            current.setAbortAction(true);
        }
        return;
    }

    if (!current.reservation_state.changes()) {
        return;
    }

    var from = previous.getValue('reservation_state');
    var allowed = TRANSITIONS[from] || [];
    if (allowed.indexOf(to) < 0) {
        gs.addErrorMessage('Invalid state change from ' + from + ' to ' + to);
        current.setAbortAction(true);
    }
})(current, previous);
